(* [comment removed for export] *)
Definition r90a_bits_exit (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 s9 s11 t3 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD TE A7 A5 : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 a0' (Z_to_bv 64 (TE + A7)) a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) (Z_to_bv 64 A7)
                  s2 s3 s4 s5 s6 s7 s8 s9 (Z_to_bv 64 32) s11 t3 (Z_to_bv 64 TE) t5 t6)
             F (Z_to_bv 64 (e_pixRotate90 + 0x30c)) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_bits : forall (n : nat) (k : Z)
    (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 s9 t3 t5 t6 ra a0 : word) F fc (m : mem) (D nD wpld T0 A7 A5 K T4 A1 : Z),
  Z.of_nat n = 32 - k -> 0 <= k < 32 -> K = k -> A5 = 4 * wpld -> T4 = T0 + 4 * wpld * k -> A1 = T0 + 4 * wpld * k + A7 ->
  1 <= wpld <= 626 -> 0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  T0 mod 4 = 0 -> A7 mod 4 = 0 -> 0 <= A7 -> D <= T0 -> T0 + 4 * wpld * 31 + A7 + 4 <= D + nD ->
  wr_at asegs m D nD -> acc asegs m D nD -> mem_inv asegs m ->
  evt asegs (r90a_bits_exit sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 s9 (Z_to_bv 64 2147450880) t3 t5 t6 F fc m D nD (T0 + 4 * wpld * 32) A7 A5)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 (Z_to_bv 64 A1) a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) (Z_to_bv 64 A7)
             s2 s3 s4 s5 s6 s7 s8 s9 (Z_to_bv 64 K) (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 T4) t5 t6)
        F (Z_to_bv 64 r90a_bt) fc None m (seg_rom asegs)).
