(* [comment removed for export] *)
Definition r90a_words_exit (sp gp tp t1 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 s11 t3 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD NW TE A7 A5 T2 : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a0' a1' s9' s10' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp (Z_to_bv 64 NW) t1 (Z_to_bv 64 T2) s0 s1 a0' a1' a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) (Z_to_bv 64 A7)
                  s2 s3 s4 s5 s6 s7 s8 s9' s10' s11 t3 (Z_to_bv 64 TE) (Z_to_bv 64 NW) t6)
             F (Z_to_bv 64 r90a_re) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_words : forall (n : nat) (jw : Z)
    (sp gp tp t1 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 t3 t6 ra a0 a1 s9 s10 : word) F fc (m : mem) (D nD S nS wpld L A7 NW JW T4 A5 T2 : Z),
  Z.of_nat n = NW - jw -> 0 <= jw < NW -> JW = jw -> T4 = D + 128 * wpld * jw -> A5 = 4 * wpld -> T2 = 128 * wpld -> t3 = Z_to_bv 64 L ->
  1 <= wpld <= 626 -> 0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  A7 mod 4 = 0 -> 0 <= A7 -> A7 + 4 <= 4 * wpld -> 128 * wpld * NW <= nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW <= S + nS ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90a_words_exit sp gp tp t1 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 (Z_to_bv 64 2147450880) t3 t6 F fc m D nD NW (D + 128 * wpld * NW) A7 A5 T2)
    (MS (mkR ra sp gp tp (Z_to_bv 64 NW) t1 (Z_to_bv 64 T2) s0 s1 a0 a1 a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) (Z_to_bv 64 A7)
             s2 s3 s4 s5 s6 s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 T4) (Z_to_bv 64 JW) t6)
