(* [comment removed for export] *)
Definition r90a_rem_exit (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 s6 s7 s8 s10 s11 t3 t5 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D nD WS TE A5 : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a1' a7' s9' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 TE) a1' a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) a7'
                  s2 s3 s4 s5 s6 s7 s8 s9' s10 s11 t3 (Z_to_bv 64 TE) t5 (Z_to_bv 64 WS))
             F (Z_to_bv 64 r90a_nx) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_rem : forall (n : nat) (j : Z)
    (sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 s7 s8 s10 t3 t5 ra a1 a7 s9 : word) F fc (m : mem) (D nD S nS wpld L A7 NW WS W48 J T4 A0 A5 : Z),
  Z.of_nat n = WS - j -> 32 * NW <= j < WS -> WS < 32 * NW + 32 -> 0 <= NW -> WS < 2^31 -> J = j -> T4 = D + 4 * wpld * j + A7 -> A0 = T4 -> A5 = 4 * wpld -> t3 = Z_to_bv 64 L ->
  1 <= wpld <= 626 -> 0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  A7 mod 4 = 0 -> 0 <= A7 -> A7 + 4 <= 4 * wpld -> 4 * wpld * WS <= nD ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 -> L mod 4 = 0 -> S <= L -> L + 4 * NW + 4 <= S + nS ->
  0 < W48 -> W48 mod 4 = 0 -> W48 + 4 <= 2^47 -> (W48 + 4 <= D \/ D + nD <= W48) -> (W48 + 4 <= 0x7fff7000 \/ 0x10007fff8000 <= W48) ->
  rw_cells asegs m W48 [C4 (Z_to_bv 64 WS)] ->
  wr_at asegs m D nD -> acc asegs m D nD -> wr_at asegs m S nS -> acc asegs m S nS -> mem_inv asegs m ->
  evt asegs (r90a_rem_exit sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 s2 s3 s4 s5 (Z_to_bv 64 W48) s7 s8 s10 (Z_to_bv 64 2147450880) t3 t5 F fc m D nD WS (D + 4 * wpld * WS + A7) A5)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 A0) a1 a2 a3 a4 (Z_to_bv 64 A5) (Z_to_bv 64 32) a7
             s2 s3 s4 s5 (Z_to_bv 64 W48) s7 s8 s9 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 T4) t5 (Z_to_bv 64 J))
