(* [comment removed for export] *)
Definition r90a_rows_exit (sp gp tp s0 s1 s2 s4 s5 s6 s7 s8 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (D nD : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a1' a2' a3' a4' a5' a6' a7' s3' s9' s10' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 s1 a0' a1' a2' a3' a4' a5' a6' a7' s2 s3' s4 s5 s6 s7 s8 s9' s10' s11 t3' t4' t5' t6')
             F (Z_to_bv 64 r90_dn) fc None m' (seg_rom asegs)
    /\ munch [(D, D + nD)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma r90a_rows : forall (n : nat) (i : Z)
    (sp gp tp s0 s2 s8 t5 t6 ra a0 a1 a7 s9 s10 t4 : word) F fc (m : mem) (D nD S nS wpld wpls WD WS NW F32 F48 F56 S1 I T3 T4 : Z),
  Z.of_nat n = WD - i -> 0 <= i < WD -> I = i -> T3 = WD -> T4 = wpls -> F56 = S1 + 56 -> 0 <= S1 ->
  1 <= WD <= 20000 -> 1 <= WS <= 20000 -> NW = WS / 32 -> wpld = (WD + 31) / 32 -> wpls = (WS + 31) / 32 -> nD = 4 * (wpld * WS) -> nS = 4 * (wpls * WD) ->
  0 < D -> D mod 4 = 0 -> D + nD <= 2^47 -> (D + nD <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < S -> S mod 4 = 0 -> S + nS <= 2^47 ->
  0 < F32 -> F32 mod 4 = 0 -> F48 = F32 + 16 -> 0 < F56 -> F56 mod 8 = 0 -> F32 + 20 <= 2^47 -> F56 + 8 <= 2^47 ->
